pub fn translateNTStatusToErrno(e: win32.NTSTATUS) bun.sys.E {
        return (switch (e) {
.SUCCESS => .SUCCESS,
.ACCESS_DENIED => .PERM,
.INVALID_HANDLE => .BADF,
.INVALID_PARAMETER => .INVAL,
.OBJECT_NAME_COLLISION => .EXIST,
.FILE_IS_A_DIRECTORY => .ISDIR,
.OBJECT_PATH_NOT_FOUND => .NOENT,
.OBJECT_NAME_NOT_FOUND => .NOENT,
.NOT_A_DIRECTORY => .NOTDIR,
.RETRY => .AGAIN,
.DIRECTORY_NOT_EMPTY => .NOTEMPTY,
.FILE_TOO_LARGE => .@"2BIG",
.NOT_SAME_DEVICE => .XDEV,
.DELETE_PENDING => .BUSY,
.SHARING_VIOLATION => (if (comptime Environment.isDebug) brk: {
        _ = bun.Output.debugWarn("Received SHARING_VIOLATION, indicates file handle should've been opened with FILE_SHARE_DELETE", .{});
        break :brk .BUSY;
} else .BUSY),
.OBJECT_NAME_INVALID => (if (comptime Environment.isDebug) brk: {
        _ = bun.Output.debugWarn("Received OBJECT_NAME_INVALID, indicates a file path conversion issue.", .{});
        _ = bun.crash_handler.dumpCurrentStackTrace(null, .{ .frame_count = 10 });
        break :brk .INVAL;
} else .INVAL),
else => {
{
